index.html.from:
.action-metric[data-band="STRONG"] b { color: #6fd18a; }
.action-metric[data-band="MODERATE"] b { color: #d8c96a; }
.action-metric[data-band="DISTANT"] b { color: #d89a6a; }
.action-metric[data-band="REMOTE"] b { color: #b06a6a; }

index.html.to:
/* One colour for every distance. A green-to-red scale grades a named
   project's grid position, and a developer may build their own
   substation: proximity to a mapped asset is not a verdict on the
   scheme. Report the measurement, let the tools do the talking. */
.action-metric b { color: #5fbdc2; }

/* A second green-to-red scale lived here for .grid-cell, which
   nothing emits any more. Removed rather than left: a dead grading
   rule is one edit away from being a live one. */

app.to:
// No band attribute is emitted, so nothing downstream can style or read
// a verdict back out of the DOM. The distance is the whole claim.
const band = "";

edits.to:
// Was the band -- "strong", "remote" -- as the whole cell. A distance is
// a measurement and a band is a verdict on somebody's scheme, so the
// cell now shows the measurement and the working stays one click away.
["_gp", "GRID", (r) => `<button class="gp-lock" type="button" data-why="${esc(r.ref)}"
  title="show the working">${r.circuit ? km(r.circuit.km) : "n/a"}</button>`],
